wb = openpyxl.Workbook()
ws = wb.active
ws.title = "功能清单"
headers = ["序号", "功能模块", "功能点", "功能描述", "操作入口/路径", "业务规则与逻辑", "状态流转", "关联数据", "备注"]
widths = [6, 16, 22, 52, 30, 52, 26, 30, 26]
hfill = PatternFill("solid", fgColor="1F4E79")
hfont = Font(name="微软雅黑", size=11, bold=True, color="FFFFFF")
bfont = Font(name="微软雅黑", size=10)
thin = Side(style="thin", color="BFBFBF")
border = Border(left=thin, right=thin, top=thin, bottom=thin)
wrap = Alignment(wrap_text=True, vertical="top")
for c, h in enumerate(headers, 1):
    cell = ws.cell(row=1, column=c, value=h)
    cell.font = hfont; cell.fill = hfill; cell.alignment = Alignment(vertical="center", horizontal="center", wrap_text=True); cell.border = border
for r, row in enumerate(ROWS, 2):
    vals = [r - 1] + list(row)
    for c, v in enumerate(vals, 1):
        cell = ws.cell(row=r, column=c, value=v)
        cell.font = bfont; cell.alignment = wrap; cell.border = border
    if r % 2 == 0:
        for c in range(1, len(headers) + 1):
            ws.cell(row=r, column=c).fill = PatternFill("solid", fgColor="F2F7FB")
for c, w in enumerate(widths, 1):
    ws.column_dimensions[get_column_letter(c)].width = w
ws.freeze_panes = "A2"
ws.auto_filter.ref = f"A1:I{len(ROWS)+1}"
out = r"C:\Users\youzi\Doubao\chats\2026-09-03\new-chat\MSA系统\MSA系统功能清单.xlsx"
wb.save(out)
print("saved", out, "rows:", len(ROWS))
